function canReadInvoice(user, invoice) {
  if (user === null || user === undefined || invoice === null || invoice === undefined) {
    return false;
  }
  if (user.id === invoice.ownerId) {
    return true;
  }
  return (
    user.role === "admin" &&
    Array.isArray(user.permissions) &&
    user.permissions.includes("billing:read")
  );
}
